        (n[3] ? '<span class="count' + (n[4] ? ' alert' : '') + '"' + (n[4] ? ' title="' + esc(n[3]) + ' reminders due"' : '') + '>' + esc(n[3]) + (n[4] ? '<span class="sr"> due</span>' : '') + '</span>' : '') + '</a>';
