  document.addEventListener('drop', function (e) { var z = e.target.closest && e.target.closest('[data-drop]'); if (!z) return; e.preventDefault(); z.classList.remove('over'); attachFiles(z.getAttribute('data-drop'), e.dataTransfer && e.dataTransfer.files); });

