  // ════════════════════════════════════════════════════════════════════════
  // Calendar export (.ics)
  // ════════════════════════════════════════════════════════════════════════
  function icsEsc(s) { return String(s || '').replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n'); }
  function icsFold(line) {
    var out = [], cur = '', bytes = 0, enc = window.TextEncoder ? new TextEncoder() : null;
    for (var ch of line) {
      var b = enc ? enc.encode(ch).length : 1;
      if (bytes + b > (out.length ? 74 : 75)) { out.push(cur); cur = ''; bytes = 0; }
      cur += ch; bytes += b;
    }
    out.push(cur);
    return out.join('\r\n ');
  }
  function openIcs() {
    modal({
      title: 'Export deadlines to a calendar (.ics)', submitLabel: 'Download .ics',
      body: '<p>Creates a calendar file you can import into Outlook, Google Calendar or Apple Calendar. It is only downloaded to this device; nothing is sent or shared.</p>' +
        '<fieldset class="grp"><legend>Include</legend>' +
        '<label class="check"><input type="checkbox" name="t_notice" checked>Notice deadlines and decide-by dates</label>' +
        '<label class="check"><input type="checkbox" name="t_decision" checked>Decision due dates</label>' +
        '<label class="check"><input type="checkbox" name="t_end">Contract ends</label>' +
        '<label class="check"><input type="checkbox" name="t_renewal">Renewals</label>' +
        '<label class="check"><input type="checkbox" name="t_price">Price increases</label></fieldset>' +
        '<div class="row2">' + F('Period', 'horizon', sel(opt('6', 'Next 6 months', '12') + opt('12', 'Next 12 months', '12') + opt('24', 'Next 24 months', '12'))) +
        F('Owner', 'owner', sel(optsOf(PEOPLE, '', null, 'All owners'))) + '</div>' +
        '<div class="row2">' + F('Alarm before notice deadlines', 'alarm', sel(opt('cat', 'Reminder window of the category', 'cat') + opt('7', '7 days', '') + opt('14', '14 days', '') + opt('30', '30 days', '') + opt('60', '60 days', '') + opt('0', 'No alarm', ''))) + '</div>',
      onSubmit: function (form) {
        var types = ['notice', 'decision', 'end', 'renewal', 'price'].filter(function (t) { return form.elements['t_' + t].checked; });
        if (!types.length) return 'Choose at least one kind of date.';
        var to = D.addDays(D.addMonths(TODAY, +v(form, 'horizon')), 0), owner = v(form, 'owner'), alarm = v(form, 'alarm');
        var lines = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Adrial Apps demo//Contracts and renewals//EN', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH', 'X-WR-CALNAME:Contract deadlines (demo)', 'X-WR-TIMEZONE:Europe/Ljubljana'];
        var stamp = new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d+Z$/, 'Z'), n = 0;
        db.contracts.forEach(function (c) {
          if (owner && c.owner !== owner) return;
          if (!(isLive(c))) return;
          eventsFor(c, TODAY, to).forEach(function (e) {
            var t = e.type === 'decide' ? 'notice' : e.type;
            if (types.indexOf(t) < 0) return;
            var dt = e.date.replace(/-/g, ''), dt2 = D.addDays(e.date, 1).replace(/-/g, '');
            var summary = (EV_NAME[e.type] || e.type) + ': ' + c.title + ' (' + c.party + ')';
            var desc = e.label + '\n' + c.no + ' · ' + (CAT[c.category] || {}).name + ' · ' + (COMP[c.company] || {}).name + '\nOwner: ' + (personName(c.owner) || 'none') + '\nNotice: ' + D.describeNotice(c) + '\nDemo data from Adrial Apps · Contracts & renewals.';
            lines.push('BEGIN:VEVENT', 'UID:' + c.id + '-' + e.type + '-' + dt + '@contracts.adrial-apps.demo', 'DTSTAMP:' + stamp, 'DTSTART;VALUE=DATE:' + dt, 'DTEND;VALUE=DATE:' + dt2,
              'SUMMARY:' + icsEsc(summary), 'DESCRIPTION:' + icsEsc(desc), 'CATEGORIES:' + icsEsc((CAT[c.category] || {}).name), 'TRANSP:TRANSPARENT');
            var days = t === 'notice' ? (alarm === 'cat' ? remindDays(c.category) : +alarm) : (alarm === '0' ? 0 : 1);
            if (days > 0) lines.push('BEGIN:VALARM', 'ACTION:DISPLAY', 'DESCRIPTION:' + icsEsc(summary), 'TRIGGER:-P' + days + 'D', 'END:VALARM');
            lines.push('END:VEVENT');
            n++;
          });
        });
        lines.push('END:VCALENDAR');
        if (!n) return 'No dates match: try a longer period or more kinds.';
        download('contract-deadlines-' + TODAY + '.ics', 'text/calendar;charset=utf-8', lines.map(icsFold).join('\r\n') + '\r\n');
        toast('Saved contract-deadlines-' + TODAY + '.ics with ' + plural(n, 'event') + ' · nothing was sent');
        return null;
      }
    });
  }

