    if (!ui.notify || !('Notification' in window) || Notification.permission !== 'granted' || !db) return;
    var seen = notified(), fresh = dueReminders().filter(function (r) { return !seen[r.key]; });
    if (!fresh.length) return;
    try {
      if (fresh.length > 3) new Notification('Contracts: ' + fresh.length + ' reminders due', { body: fresh.slice(0, 3).map(function (r) { return fd(r.date) + ' · ' + r.c.title; }).join('\n') + '\n…', tag: 'contracts-summary' });
      else fresh.forEach(function (r) { var nn = new Notification((EV_NAME[r.type] || 'Reminder') + ' ' + daysText(r.days) + ': ' + r.c.title, { body: r.text + '\n' + r.c.party, tag: 'contracts-' + r.key }); nn.onclick = function () { window.focus(); go('#/contracts/' + encodeURIComponent(r.c.id)); }; });
    } catch (e) { return; }
    fresh.forEach(function (r) { seen[r.key] = TODAY; });
    var keys = Object.keys(seen); if (keys.length > 400) keys.slice(0, keys.length - 400).forEach(function (k) { delete seen[k]; });
